"""Assemble reports/phase0_report.md from results/phase0/*.csv, runs/brms/*_{fixef,ranef,diag}.csv and reports/data_audit.md.
Missing pieces are marked as pending so the report can be regenerated as fits complete."""
import json, subprocess, sys, platform, numpy as np, pandas as pd
from pathlib import Path
from collective_id.paths import RESULTS, REPORTS, RUNS, ROOT
out = RESULTS / "phase0"; L = []
def P(x=""): L.append(x)
def md(df, floatfmt=".3f"): return df.to_markdown(index=False, floatfmt=floatfmt)
def exists(p): return Path(p).exists() and Path(p).stat().st_size > 1

P("# Phase 0 report — reproduction and data audit\n")
P("Generated by `scripts/09_phase0_report.py`. Date: 2026-09-24. All numbers below were measured in this project; paper values are quoted from Chirkov et al. (2026, *Nat Commun* 17:10133) text/figures only where verified in `refs/chirkov2026_clean.txt`.\n")
P("## 1. Execution environment\n")
try:
    tv = subprocess.run([str(ROOT / ".venv/bin/python"), "-c", "import torch,numpy,pandas,mesa;print(torch.__version__, torch.cuda.is_available(), numpy.__version__, pandas.__version__, mesa.__version__)"], capture_output=True, text=True).stdout.strip().split()
except Exception: tv = ["?"] * 5
rv = subprocess.run(["bash", "-lc", "~/micromamba/bin/micromamba run -r ~/micromamba -n rbrms Rscript -e 'cat(R.version.string, as.character(packageVersion(\"brms\")), as.character(packageVersion(\"cmdstanr\")), cmdstanr::cmdstan_version())' 2>/dev/null"], capture_output=True, text=True).stdout.strip()
P(f"- Host: {platform.platform()}, 24 CPU cores, 91 GB RAM, RTX 5080 16 GB (CUDA available: {tv[1]}).")
P(f"- Python 3.12 via uv; torch {tv[0]}, numpy {tv[2]}, pandas {tv[3]}, mesa {tv[4]} (paper's ABM requires the mesa 2.x API).")
P(f"- R (micromamba env `rbrms`): {rv}. rstan had to be rebuilt from source (conda binary was ABI-incompatible with RcppParallel).")
P("- No sudo, no gfortran on the host; everything runs in user space.")
if exists(out / "abm_timing.json"):
    t = json.load(open(out / "abm_timing.json")); P(f"- Paper ABM (mesa 2.2.4, single core): **{t['sec_per_run_solo']:.3f} s per 900-step solo run, {t['sec_per_run_group5']:.3f} s per 900-step 5-agent run**.")
P()
P("## 2. Data audit (expected vs measured)\n")
P("Full audit: `reports/data_audit.md`. Key points:\n")
P("- 621 analysed participants, cell counts identical to the paper (fast A/NP/VP/FP = 73/72/86/74; slow = 71/80/79/86).")
P("- **103 groups** (65 × 5 persons, 38 × 4 persons) — not ≈95; 4-person groups are groups with one excluded member, kept by the paper.")
P("- 10 Hz traces (processed_traces.csv: x, z, rotation, distance, visibility, in/out-degree, social features) for all 737 recorded participants; raw traces with score and resource position for 580 sessions (download in progress, see logs/download.log).")
P("- 1 Hz table: steps 20–880 (861 per participant); states tracking 52.2 %, searching 45.3 %, mixed 2.5 %.")
P("- Discrepancy: discovery-event thresholds are 2 s in code vs '5 s' in the paper text; the code definition reproduces the paper's event counts exactly (829 fast / 261 slow).")
P("- `score_first_half` is documented in the OSF README but absent from subject_data.csv.")
P()
P("## 3. Deviations from AGENT_SPEC defaults\n")
P("- brms sampling budget reduced to 4 × (1000 warm-up + 1500 draws) with 5 threads/chain (paper: 4 × (2000 + 3000), 100 threads); convergence diagnostics reported in §4.5.")
P("- Fig 2A/3A/3B reproduced with raw means ± 95 % CI instead of Bayesian Beta/Poisson/logistic regressions (allowed by §3.1-2).")
P("- Angle normalisers fixed to geometric constants (45.75°, 180°) instead of sample maxima (see questions.md).")
P("- The paper's tracking model has no participant-level random slope for distance; teacher signal = the paper's 6 random effects.")
P()
P("## 4. Results\n")
P("### 4.1 Performance (Fig 2A)\n")
if exists(out / "fig2A_performance_by_condition.csv"):
    perf = pd.read_csv(out / "fig2A_performance_by_condition.csv"); P(md(perf[["condition_resource", "condition_signaling", "n", "score_mean", "score_ci", "ttime_mean", "ttime_ci", "teff_mean", "teff_ci"]].rename(columns={"ttime_mean": "tracking_time_prop", "teff_mean": "eff_pts_per_s"}), ".2f")); P()
    P("Direction checks vs paper (`fig2A_direction_checks.csv`):\n"); P(md(pd.read_csv(out / "fig2A_direction_checks.csv"))); P()
    P("Paper: slow FP > VP > NP ≳ A in points; fast FP > A > VP > NP; groups gain mainly through tracking time; only FP matches/exceeds singletons' efficiency. All reproduced. (The 'fast tracking time groups > A' row is my own extra check, not a paper claim: in fast, NP/VP tracking time ≈ A, as the paper states.) Figure: `results/phase0/fig2A_performance.png`.\n")
P("### 4.2 Visibility networks (Fig 3A, 3B, Supp Fig 9)\n")
if exists(out / "fig3A_degree_by_condition.csv"):
    P(md(pd.read_csv(out / "fig3A_degree_by_condition.csv"))); P(); P("FP has the highest in- and out-degree at both speeds (paper Fig 3A). Figure: `fig3A_degree.png`.\n")
    P(md(pd.read_csv(out / "suppfig9_in_out_correlation.csv"))); P(); P("Participant-level in–out degree correlations are strongly negative in every cell (paper Supp Fig 9); in-degree correlates positively and out-degree negatively with score, strongest in FP-fast (paper Supp Fig 10).\n")
    P(md(pd.read_csv(out / "fig3B_adaptive_social_info.csv"))); P(); P("Contrasts (probability that a visible other is closer to the centre; participant-level means):\n"); P(md(pd.read_csv(out / "fig3B_contrasts.csv"))); P()
    P("Paper (posterior contrasts): fast/search FP−NP 0.20, FP−VP 0.13; slow/search 0.12, 0.08; fast/track 0.14, 0.10; slow/track 0.05, 0.02. Ordering FP > VP > NP reproduced in all four cells; magnitudes differ (raw participant means vs. hierarchical logistic model with random effects), largest gap in fast/searching.\n")
P("### 4.3 Resource discovery events (Fig 3C)\n")
if exists(out / "fig3C_event_counts.csv"):
    P(md(pd.read_csv(out / "fig3C_event_counts.csv"))); P(); P("Totals: fast 829, slow 261 — identical to the paper. Discoverer in-degree (fast): FP peaks at ≈8–10 s (`fig3C_discoverer_indegree_peaks.csv`):\n"); P(md(pd.read_csv(out / "fig3C_discoverer_indegree_peaks.csv"))); P()
    P("FP − NP ≈ 0.77 in-degree at 10 s (paper 0.80), FP − VP ≈ 0.45 (paper 0.62; raw means vs GP regression). Figure: `fig3C_discovery.png`.\n")
P("### 4.4 Computational model (Fig 4C, D) — re-estimated with brms\n")
for tag, label in [("tracking_all", "Tracking"), ("search_all", "Search")]:
    fe = RUNS / "brms" / f"{tag}_fixef.csv"
    if exists(fe):
        f = pd.read_csv(fe); dg = pd.read_csv(RUNS / "brms" / f"{tag}_diag.csv").iloc[0]
        P(f"**{label} model** — rows {int(dg.n_rows)}, participants {int(dg.n_participants)}, fit {dg.fit_min:.0f} min, max R̂ {dg.max_rhat:.3f}, min bulk ESS {dg.min_bulk_ess:.0f}, divergences {int(dg.n_divergent)}.\n")
        keep = f[f.coef.str.contains("Detector|withSocInfo1", regex=True) & ~f.coef.str.contains("withSocInfo0")]
        keep = keep.assign(cond=keep.coef.str.extract(r"SignalingType(\w+?):")[0], speed=keep.coef.str.extract(r"ResourceSpeed(\w+?):")[0], feature=keep.coef.str.replace(r"SignalingType\w+?:ResourceSpeed\w+?:", "", regex=True).str.replace("withSocInfo1:", ""))
        tab = keep.pivot_table(index=["feature", "speed"], columns="cond", values="Estimate").reindex(columns=["A", "NP", "VP", "FP"]).reset_index()
        P(tab.to_markdown(index=False, floatfmt=".3f")); P()
        chk = []
        if label == "Tracking":
            det = tab[tab.feature == "Detector"].set_index("speed")
            for sp in ["fast", "slow"]: chk.append(f"Detector weight A ({det.loc[sp,'A']:.3f}) largest vs FP ({det.loc[sp,'FP']:.3f}) [{sp}]: {'OK' if det.loc[sp,'A'] > det.loc[sp,'FP'] else 'NOT reproduced'}")
        for feat in ["SocPosInFOV:SocQual", "SocMovDir:SocQual"]:
            q = tab[tab.feature == feat].set_index("speed")
            for sp in ["fast", "slow"]:
                if sp in q.index: chk.append(f"{feat} FP ({q.loc[sp,'FP']:.3f}) > NP ({q.loc[sp,'NP']:.3f}) & VP ({q.loc[sp,'VP']:.3f}) [{sp}]: {'OK' if q.loc[sp,'FP'] > max(q.loc[sp,'NP'], q.loc[sp,'VP']) else 'NOT reproduced'}")
        for c in chk: P(f"- {c}")
        P()
    else:
        P(f"**{label} model**: pending (`runs/brms/{tag}_*.csv` not yet written).\n")
if exists(RUNS / "brms" / "tracking_all_ranef.csv"):
    re = pd.read_csv(RUNS / "brms" / "tracking_all_ranef.csv"); s = re.groupby("coef").agg(re_sd=("estimate", "std"), mean_post_sd=("sd", "mean")).reset_index(); s["signal_to_noise"] = s.re_sd / s.mean_post_sd
    P("Participant random effects (tracking model; saved to `data/processed/individual_weights.csv`): between-participant SD vs mean posterior SD:\n"); P(md(s)); P()
P("### 4.5 Noise ceiling: split-half retest reliability of the random effects\n")
rel = out / "split_half_reliability.csv"
if exists(rel) and len(pd.read_csv(rel)):
    P(md(pd.read_csv(rel))); P(); P("Interpretation: the split-half r is an upper bound for how well any transfer model can predict the full-session random effect of a feature from other data; features with low r have a low ceiling. Estimator 'eb' = GPU empirical-Bayes fit of the same model (`scripts/05_teacher_eb.py`); 'brms' rows appear when the queued brms split-half fits finish.\n")
else: P("Pending: split-half fits.\n")
P("### 4.5b Provisional EB teacher vs brms\n")
cmpf = out / "teacher_eb_vs_brms.csv"
if exists(cmpf) and len(pd.read_csv(cmpf)): P(md(pd.read_csv(cmpf))); P()
else: P("Pending: brms full fits still running; EB fixed effects (tracking) reproduce the paper's ordering (A largest detector weight; FP largest social and quality-interaction weights; VP between NP and FP) — see `runs/eb/tracking_all_fixef.csv`.\n")
if exists(RUNS / "eb" / "tracking_all_fixef.csv"):
    f = pd.read_csv(RUNS / "eb" / "tracking_all_fixef.csv"); f = f.assign(cond=f.coef.str.extract(r"SignalingType(\w+?):")[0], speed=f.coef.str.extract(r"ResourceSpeed(\w+?):")[0], feature=f.coef.str.replace(r"SignalingType\w+?:ResourceSpeed\w+?:", "", regex=True))
    P("EB tracking-model fixed effects (per condition × speed):\n"); P(f.pivot_table(index=["feature", "speed"], columns="cond", values="Estimate").reindex(columns=["A", "NP", "VP", "FP"]).reset_index().to_markdown(index=False, floatfmt=".3f")); P()
P("### 4.6 Agent-based model (Fig 5B)\n")
if exists(out / "abm_fig5B_group_minus_solo.csv"):
    g = pd.read_csv(out / "abm_fig5B_group_minus_solo.csv"); P(md(g[["resource_speed", "k", "pcr", "tracking_time", "d_pcr", "d_tracking_time", "n_runs", "sec_per_run"]])); P()
    r4 = g[g.resource_speed == 0.4]; ok = bool((r4[r4.k == 10][["d_pcr", "d_tracking_time"]] > 0).all().all() and (r4[r4.k < 10].d_pcr < 0).all())
    P(f"Qualitative check (paper Fig 5B): at 40 % speed only highly selective agents (k = 10) exceed solitary agents in **both** tracking time and efficiency, non-selective agents lose efficiency — **{'reproduced' if ok else 'NOT reproduced'}** (100 runs per cell; paper used 2000). Figure: `abm_fig5B.png`.\n")
P("## 5. Pass/fail against §3.1\n")
P("- Performance ordering (Fig 2A): **pass**.\n- Visibility networks (Fig 3A/B, Supp Fig 9): **pass** (orderings; magnitudes not directly comparable).\n- Discovery events (Fig 3C): **pass** (event counts exact; FP in-degree peak ≈ 8–10 s).")
if exists(RUNS / "brms" / "tracking_all_fixef.csv"): P("- Computational model fixed effects: see checks in §4.4.")
else: P("- Computational model fixed effects: pending.")
P("- ABM Fig 5B: see §4.6.\n")
P("## 6. Anomalies / unresolved\n")
P("- OSF download is rate-limited (HTTP 429); raw traces (needed only for score/resource position) are still downloading; not needed for Phases 0–1 (processed tables suffice).\n- brms with the paper's `constant(0)` prior names worked unchanged in brms 2.23 (38 zero-fixed b terms, 4 zero sd terms, as in the paper's Rmd).\n- One analysed participant has time_in_experiment = 20.0 min (an Alone participant, where validity uses resource-frame duplicates instead).\n")
P("## 7. Unverified\n")
P("- Supplementary tables/figures of the paper were not available (only main text PDF); paper numbers quoted are from the main text.\n- Whether Unity's heading convention (atan2(x, z)) matters for any sign-sensitive feature: only absolute angles are used by the models, so it does not affect Phase 1 features.\n")
P("## 8. Questions for the human\n")
P("See `reports/questions.md` (4-person groups in Phase 3; reduced brms budget; distance random slope; normalisation constants).\n")
(REPORTS / "phase0_report.md").write_text("\n".join(L)); print("\n".join(L)[:3000])
